<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ubuntu‑style Desktop Demo</title>
<style>
html,body{
    margin:0;padding:0;height:100%;overflow:hidden;
    font-family:sans-serif;
}
#desktop{
    position:relative;width:100vw;height:100vh;
    background:#1d1f21 url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22100%22 height=%22100%22 viewBox=%220 0 100 100%22%3E%3Crect width=%22100%22 height=%22100%22 fill=%22%23333%22/%3E%3Ccircle cx=%2250%22 cy=%2250%22 r=%2230%22 fill=%22%23444%22 opacity=%220.2%22/%3E%3C/svg%3E') repeat;
}
#taskbar{
    position:fixed;bottom:0;left:0;right:0;height:48px;
    background:#111;color:#eee;
    display:flex;align-items:center;padding:0 12px;gap:12px;
    box-shadow:0 -2px 6px rgba(0,0,0,.7);
    z-index:1000;
}
#taskbar button{
    background:#333;border:none;color:#fff;padding:6px 12px;
    cursor:pointer;border-radius:4px;
}
#taskbar button:hover{background:#444;}
.window{
    position:absolute;min-width:360px;min-height:240px;
    background:#2c001e;color:#ddd;
    border:1px solid #555;box-shadow:2px 2px 10px rgba(0,0,0,.7);
    display:none;flex-direction:column;
    resize:both;overflow:auto;
}
.title-bar{
    background:#111;padding:4px 8px;
    cursor:move;user-select:none;
    display:flex;justify-content:space-between;align-items:center;
}
.title-bar span{font-weight:bold;}
.win-close{
    background:#c33;color:#fff;border:none;width:20px;height:20px;
    line-height:18px;text-align:center;padding:0;margin:0;
    cursor:pointer;font-weight:bold;
}
.content{
    flex:1;display:flex;flex-direction:column;padding:8px;
    overflow:auto;
}
/* Files app */
#files-header{
    margin-bottom:8px;display:flex;align-items:center;gap:8px;
}
#files-list{
    list-style:none;padding:0;margin:0;flex:1;overflow:auto;
}
.fs-item{
    padding:4px 8px;cursor:pointer;
}
.fs-item:hover{background:#400030;}
/* Notepad */
#tabs{
    display:flex;gap:4px;align-items:center;margin-bottom:4px;
}
.tab{
    background:#444;color:#fff;padding:4px 8px;cursor:pointer;
    border-radius:4px 4px 0 0;
}
.tab.active{background:#666;}
#new-tab{
    background:#555;color:#fff;border:none;padding:4px 8px;
    cursor:pointer;border-radius:4px;
}
#editor{
    flex:1;width:100%;resize:none;background:#111;color:#eee;
    border:none;padding:8px;box-sizing:border-box;
    font-family:monospace;font-size:14px;
}
</style>
</head>
<body>
<div id="desktop">
    <div id="taskbar">
        <button id="open-files">Files</button>
        <button id="open-notepad">Notepad</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window">
        <div class="title-bar"><span>Files</span><button class="win-close">✕</button></div>
        <div class="content">
            <div id="files-header">
                <button id="files-up">⬆ Up</button>
                <span id="files-path">/</span>
            </div>
            <ul id="files-list"></ul>
        </div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window">
        <div class="title-bar"><span>Notepad</span><button class="win-close">✕</button></div>
        <div class="content">
            <div id="tabs"><button id="new-tab">＋</button></div>
            <textarea id="editor" spellcheck="false"></textarea>
        </div>
    </div>
</div>

<script>
// ---------- Utility ----------
function $(sel){return document.querySelector(sel);}
function $all(sel){return Array.from(document.querySelectorAll(sel));}

// ---------- Desktop & Taskbar ----------
$('#open-files').addEventListener('click',()=>showWindow('#files-window'));
$('#open-notepad').addEventListener('click',()=>showWindow('#notepad-window'));

function showWindow(id){
    const win=document.querySelector(id);
    win.style.display='flex';
    bringToFront(win);
    // centre if first time
    if(!win.dataset.initialized){
        win.style.left=`calc(50% - ${win.offsetWidth/2}px)`;
        win.style.top=`calc(50% - ${win.offsetHeight/2}px)`;
        win.dataset.initialized='true';
    }
}
$all('.win-close').forEach(btn=>btn.addEventListener('click',e=>{
    e.target.closest('.window').style.display='none';
}));

// Dragging windows
let dragInfo=null;
$all('.title-bar').forEach(bar=>{
    bar.addEventListener('mousedown',e=>{
        const win=e.currentTarget.parentElement;
        bringToFront(win);
        dragInfo={win,offsetX:e.clientX-win.offsetLeft, offsetY:e.clientY-win.offsetTop};
        e.preventDefault();
    });
});
document.addEventListener('mousemove',e=>{
    if(!dragInfo)return;
    const {win,offsetX,offsetY}=dragInfo;
    win.style.left=(e.clientX-offsetX)+'px';
    win.style.top=(e.clientY-offsetY)+'px';
});
document.addEventListener('mouseup',()=>{dragInfo=null;});

function bringToFront(el){
    const maxZ= Math.max(...$all('.window').map(w=>+w.style.zIndex||0));
    el.style.zIndex=maxZ+1;
}

// ---------- Files App ----------
const fsStructure = {
    "/": {
        bin: {}, etc: {}, home: {
            user: {
                Documents: {},
                Downloads: {},
                Pictures: {}
            }
        },
        usr: {}, var: {}
    }
};

let cwd = ['/']; // array parts, root is ['/']

function resolvePath(){
    if(cwd.length===1) return '/';
    return cwd.slice(1).join('/');
}
function getNode(){
    let node = fsStructure["/"];
    for(let i=1;i<cwd.length;i++){
        node = node[cwd[i]];
    }
    return node;
}
function renderFiles(){
    $('#files-path').textContent = resolvePath() || '/';
    const list=$('#files-list');
    list.innerHTML='';
    const node=getNode();
    Object.keys(node).sort().forEach(name=>{
        const li=document.createElement('li');
        li.className='fs-item';
        li.textContent=name;
        li.dataset.name=name;
        li.dataset.type= typeof node[name]==='object' ? 'folder':'file';
        list.appendChild(li);
    });
}
$('#files-up').addEventListener('click',()=>{
    if(cwd.length>1){ cwd.pop(); renderFiles();}
});
$('#files-list').addEventListener('dblclick',e=>{
    const item=e.target.closest('.fs-item');
    if(!item) return;
    if(item.dataset.type!=='folder') return;
    cwd.push(item.dataset.name);
    renderFiles();
});
// optional click highlight (not required)

// initialise files app
renderFiles();

// ---------- Notepad App ----------
const STORAGE_KEY='notepad_state_v1';

let npState={tabs:[],active:null};

function loadState(){
    const raw=localStorage.getItem(STORAGE_KEY);
    if(raw){
        try{npState=JSON.parse(raw);}catch(e){}
    }
    if(npState.tabs.length===0){
        createTab(); // at least one tab
    }else{
        npState.tabs.forEach(t=>addTabElement(t.id,t.title||'Untitled'));
        activateTab(npState.active);
    }
}
function saveState(){
    localStorage.setItem(STORAGE_KEY,JSON.stringify(npState));
}
function createTab(title='Untitled'){
    const id='t'+Date.now()+Math.random().toString(36).substr(2,5);
    const tabObj={id,content:'',title};
    npState.tabs.push(tabObj);
    npState.active=id;
    addTabElement(id,title);
    activateTab(id);
    saveState();
}
function addTabElement(id,title){
    const tab=document.createElement('div');
    tab.className='tab';
    tab.dataset.id=id;
    tab.textContent=title;
    $('#tabs').insertBefore(tab,$('#new-tab'));
    tab.addEventListener('click',()=>activateTab(id));
}
function activateTab(id){
    npState.active=id;
    $all('.tab').forEach(t=>t.classList.toggle('active',t.dataset.id===id));
    const tabObj=npState.tabs.find(t=>t.id===id);
    $('#editor').value=tabObj?.content||'';
    saveState();
}
$('#new-tab').addEventListener('click',()=>createTab());

$('#editor').addEventListener('input',e=>{
    const txt=e.target.value;
    const tab=npState.tabs.find(t=>t.id===npState.active);
    if(tab){tab.content=txt;saveState();}
});

// Load saved state on startup
loadState();

// When notepad window opens, ensure UI reflects state
$('#open-notepad').addEventListener('click',()=>setTimeout(()=>{$('#editor').focus()},0));

</script>
</body>
</html>
